      last_attempted_at: String(source.last_attempted_at || ''),
      attempt_count: String(source.attempt_count || '').trim() || '1',
      status_reason: 'enrichment_error',
      error_type: 'enrichment_error',
      error_message: errorText,
      retry_eligible: 'true',
      source_row_created_at: String(source.source_row_created_at || ''),
      source_row_updated_at: String(source.source_row_updated_at || '')
    },
    pairedItem: item.pairedItem
  }];
});

